const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the Area of Interest (AOI) around Paradise, California.
  // The historical Camp Fire started on Nov 8, 2018 near this location.
  const paradiseCa = ee.Geometry.Point([-121.6219, 39.7594]);
  const aoi = paradiseCa.buffer(10000); // 10 km buffer to represent the "near" area.

  // Define the date range.
  const startDate = '2018-11-07';
  const endDate = '2018-11-10';

  // 2. Data Acquisition & Check
  // Use the MODIS Thermal Anomalies/Fire collection, which is ideal for detecting active fires.
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14DL')
    .filterDate(startDate, endDate)
    .filterBounds(aoi);

  // Check the number of fire detections (each detection is a feature in the collection).
  const fireCount = fireCollection.size().getInfo();

  // 3. Validation & Final Answer
  console.log(`Query Period: ${startDate} to ${endDate}`);
  console.log(`Location: Paradise, CA (10km buffer)`);
  console.log(`MODIS Active Fire Detections: ${fireCount}`);

  if (fireCount > 0) {
    console.log('Evidence: Active fire points were detected within the specified area and time frame.');
    console.log('A');
  } else {
    // This case would mean no fires were detected by the satellite in this period.
    console.log('Evidence: No active fire points were detected.');
    console.log('B');
  }
}

